#include <cstddef>
#include <cstdint>
#include <array>
namespace {template<bool Max>struct Heap{std::array<std::int64_t,256>v{};std::size_t n=0;void push(std::int64_t x){auto i=n++;v[i]=x;while(i){auto p=(i-1)/2;if(!(Max?v[p]<v[i]:v[p]>v[i]))break;std::swap(v[p],v[i]);i=p;}}std::int64_t pop(){auto x=v[0];v[0]=v[--n];std::size_t i=0;for(;;){auto l=2*i+1,r=l+1,b=i;if(l<n&&(Max?v[l]>v[b]:v[l]<v[b]))b=l;if(r<n&&(Max?v[r]>v[b]:v[r]<v[b]))b=r;if(b==i)break;std::swap(v[i],v[b]);i=b;}return x;}};void store(std::int64_t x,std::uint8_t*out,std::size_t p){auto u=static_cast<std::uint64_t>(x);for(std::size_t b=0;b<8;b++)out[p+b]=static_cast<std::uint8_t>(u>>(8*b));}}
extern "C" std::int64_t median_of_running_array_integer(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap) noexcept {if(!in||len<2||in[0]<1||in[0]>256||len!=static_cast<std::size_t>(in[0])+1)return -1;auto n=static_cast<std::size_t>(in[0]);for(std::size_t i=0;i<n;i++)if(in[i+1]<-1000000||in[i+1]>1000000)return -1;if(!out||cap<n*8)return -2;Heap<true>lo;Heap<false>hi;for(std::size_t i=0;i<n;i++){auto x=in[i+1];if(hi.n&&x<hi.v[0])lo.push(x);else hi.push(x);if(lo.n>hi.n+1)hi.push(lo.pop());else if(hi.n>lo.n+1)lo.push(hi.pop());auto m=lo.n==hi.n?(lo.v[0]+hi.v[0])/2:(lo.n>hi.n?lo.v[0]:hi.v[0]);store(m,out,i*8);}return static_cast<std::int64_t>(n*8);}
